L48_1 = "\227\129\147\227\129\174\228\184\150\231\149\140\227\129\175\227\130\130\227\129\134\227\129\152\227\129\141\230\187\133\228\186\161\227\129\153\227\130\139\227\128\130\227\129\160\227\129\140\227\128\129\229\174\135\229\174\153\227\129\171\233\128\131\227\129\146\227\130\139\227\129\147\227\129\168\227\129\175\228\184\141\229\143\175\232\131\189\227\129\160\227\128\130"
