L47_1.m_Talk_VTN = L48_1
L48_1 = "\232\191\153\228\184\170\228\184\150\231\149\140\228\184\128\229\174\154\228\188\154\231\129\173\228\186\161\227\128\130\228\189\134\230\152\175\230\136\145\228\187\172\230\151\160\230\179\149\233\128\131\229\144\145\229\174\135\229\174\153\227\128\130\229\155\160\228\184\186\233\130\163\230\152\175\228\184\141\229\143\175\232\131\189\231\154\132\227\128\130"
